package org.springframework.samples.petclinic.acceptance;

import org.junit.jupiter.api.Test;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.content;
import tools.jackson.databind.node.ObjectNode;
import org.springframework.test.web.servlet.ResultActions;

class ScratchProblemJsonTest extends AcceptanceBase {

	private void assertProblem(ResultActions ra, int code) throws Exception {
		ra.andExpect(status().is(code))
				.andExpect(content().contentTypeCompatibleWith("application/problem+json"))
				.andExpect(jsonPath("$.type").exists())
				.andExpect(jsonPath("$.title").exists())
				.andExpect(jsonPath("$.status").value(code))
				.andExpect(jsonPath("$.detail").exists());
	}

	@Test
	void invalidEmail400() throws Exception {
		ObjectNode o = structuredOwner();
		o.put("email", "not-an-email");
		assertProblem(createOwner(o), 400);
	}

	@Test
	void duplicateIdentity409() throws Exception {
		ObjectNode o = structuredOwner();
		createOwnerOk(o.deepCopy());
		ObjectNode dup = structuredOwner();
		dup.put("firstName", o.get("firstName").asText());
		dup.put("lastName", o.get("lastName").asText());
		dup.put("telephone", o.get("telephone").asText());
		dup.put("city", o.get("city").asText());
		assertProblem(createOwner(dup), 409);
	}

	@Test
	void dailyLimit429() throws Exception {
		// hard to reach 100; skip - just document
	}
}
